import React, { useRef, useState } from "react";
import emailjs from "emailjs-com";
import { motion } from "framer-motion";

function Contact() {
  const form = useRef();
  const [submitted, setSubmitted] = useState(false);

  const sendEmail = (e) => {
    e.preventDefault();

    emailjs.sendForm(
      "service_3blhwqe",   // tumhara service ID
      "template_70yboqt",  // tumhara template ID
      form.current,
      "Syc-g1XHe4aoM8XIB"  // tumhara public key
    ).then(
      (result) => {
        // ✅ Success animation trigger
        setSubmitted(true);

        // ✅ Auto refresh (clear form fields)
        form.current.reset();

        // Animation ko 3 sec baad hide karna
        setTimeout(() => setSubmitted(false), 3000);
      },
      (error) => {
        alert("Failed to send message. Try again!");
      }
    );
  };

  return (
    <section id="contact" className="p-10 bg-gray-900 text-white text-center">
      <h2 className="text-3xl font-bold mb-6">Contact Me</h2>
      
      {/* Contact Form */}
      <form ref={form} onSubmit={sendEmail} className="max-w-md mx-auto space-y-4">
        <input
          type="text"
          name="user_name"
          placeholder="Your Name"
          className="w-full p-2 rounded-md text-black"
          required
        />
        <input
          type="email"
          name="user_email"
          placeholder="Your Email"
          className="w-full p-2 rounded-md text-black"
          required
        />
        <textarea
          name="message"
          placeholder="Your Message"
          className="w-full p-2 rounded-md text-black"
          rows="5"
          required
        />
        <button
          type="submit"
          className="px-4 py-2 bg-blue-600 hover:bg-blue-700 rounded-lg text-white"
        >
          Send Message
        </button>
      </form>

      {/* ✅ Success Animation */}
      {submitted && (
        <motion.div
          initial={{ opacity: 0, scale: 0.8 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0 }}
          transition={{ duration: 0.5 }}
          className="mt-4 text-green-400 font-semibold"
        >
          ✅ Message Sent Successfully!
        </motion.div>
      )}

      {/* Static Info */}
      <div className="mt-8 space-y-2">
        <p>Email: <a href="mailto:Rahul1322rahul@gmail.com" className="text-blue-400">Rahul1322rahul@gmail.com</a></p>
        <p>Phone: <a href="tel:+917836997866" className="text-blue-400">+91-7836-99-7866</a></p>
        <p>GitHub: <a href="https://github.com/Rahul-manjhi" target="_blank" rel="noopener noreferrer" className="text-blue-400">Rahul</a></p>
      </div>
    </section>
  );
}

export default Contact;
